// Iyzico SDK implementation with Vercel compatibility

import Iyzipay from 'iyzipay'
// eslint-disable-next-line @typescript-eslint/no-require-imports
const iyziUtils = require('iyzipay/lib/utils') as {
  generateRandomString: (n: number) => string
  generateAuthorizationHeaderV2: (
    iyziWsHeaderName: string,
    apiKey: string,
    separator: string,
    secretKey: string,
    uri: string,
    body: Record<string, unknown>,
    randomString: string
  ) => string
}

let iyzipayInstance: Iyzipay | null = null

export function getIyzicoInstance(): Iyzipay | null {
  if (iyzipayInstance) {
    return iyzipayInstance
  }

  const apiKey = process.env.IYZICO_API_KEY?.trim()
  const secretKey = process.env.IYZICO_SECRET_KEY?.trim()
  
  if (!apiKey || !secretKey) {
    console.error('❌ Iyzico credentials missing')
    return null
  }
  
  const baseUrl = process.env.IYZICO_BASE_URL?.trim() || 'https://sandbox-api.iyzipay.com'
  const isSandbox = baseUrl.includes('sandbox')
  
  console.log(`🔧 Iyzico SDK: ${isSandbox ? 'SANDBOX 🧪' : 'PRODUCTION 🚀'}`)
  console.log(`   Base URL: ${baseUrl}`)
  
  try {
    iyzipayInstance = new Iyzipay({
      apiKey: apiKey,
      secretKey: secretKey,
      uri: baseUrl
    })
    return iyzipayInstance
  } catch (error) {
    console.error('❌ Failed to initialize Iyzico SDK:', error)
    return null
  }
}

export function getIyzicoCredentials() {
  const apiKey = process.env.IYZICO_API_KEY?.trim()
  const secretKey = process.env.IYZICO_SECRET_KEY?.trim()
  
  if (!apiKey || !secretKey) {
    return null
  }
  
  const baseUrl = process.env.IYZICO_BASE_URL?.trim() || 'https://sandbox-api.iyzipay.com'
  
  return { apiKey, secretKey, baseUrl }
}

// Create payment using Iyzico SDK
export async function createPayment(paymentRequest: any): Promise<any> {
  const iyzipay = getIyzicoInstance()
  
  if (!iyzipay) {
    throw new Error('Iyzico SDK not initialized')
  }
  
  console.log('📤 Sending payment via Iyzico SDK')
  
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Iyzico payment timed out')), 10000)
    iyzipay.payment.create(paymentRequest, (err: any, result: any) => {
      clearTimeout(timeout)
      if (err) {
        console.error('❌ SDK Error:', err)
        reject(err)
        return
      }
      
      console.log('📥 Response:', {
        status: result.status,
        errorCode: result.errorCode,
        errorMessage: result.errorMessage,
        paymentId: result.paymentId
      })
      
      resolve(result)
    })
  })
}

// 3DS initialize (zorunlu 3DS için)
export async function initialize3DSPayment(paymentRequest: any): Promise<any> {
  const iyzipay = getIyzicoInstance()
  if (!iyzipay) {
    throw new Error('Iyzico SDK not initialized')
  }

  console.log('📤 Sending 3DS initialize via Iyzico SDK')

  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Iyzico initialization timed out')), 10000)
    ;(iyzipay as any).threedsInitialize.create(paymentRequest, (err: any, result: any) => {
      clearTimeout(timeout)
      if (err) {
        console.error('❌ 3DS Initialize SDK Error:', err)
        reject(err)
        return
      }
      console.log('📥 3DS Initialize Response:', {
        status: result?.status,
        errorCode: result?.errorCode,
        errorMessage: result?.errorMessage,
        paymentId: result?.paymentId,
      })
      resolve(result)
    })
  })
}

// 3DS complete (callback sonrası ödeme tamamlama)
export async function complete3DSPayment(payload: {
  conversationId: string
  paymentId: string
  conversationData: string
}): Promise<any> {
  const iyzipay = getIyzicoInstance()
  if (!iyzipay) {
    throw new Error('Iyzico SDK not initialized')
  }

  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Iyzico completion timed out')), 10000)
    ;(iyzipay as any).threedsPayment.create(
      {
        locale: 'tr',
        conversationId: payload.conversationId,
        paymentId: payload.paymentId,
        conversationData: payload.conversationData,
      },
      (err: any, result: any) => {
        clearTimeout(timeout)
        if (err) {
          console.error('❌ 3DS Complete SDK Error:', err)
          reject(err)
          return
        }
        console.log('📥 3DS Complete Response:', {
          status: result?.status,
          errorCode: result?.errorCode,
          errorMessage: result?.errorMessage,
          paymentId: result?.paymentId,
          paymentStatus: result?.paymentStatus,
        })
        resolve(result)
      }
    )
  })
}

/**
 * 3DS v2 tamamlama — conversationData boş geldiğinde iyzico önerisi:
 * https://docs.iyzico.com/odeme-metotlari/api/3ds/3ds-entegrasyonu/3ds-tamamlama
 * (payment/v2/3dsecure/auth — paymentId, paidPrice, basketId, currency)
 */
export async function complete3DSPaymentV2(payload: {
  conversationId: string
  paymentId: string
  paidPrice: string
  basketId: string
}): Promise<any> {
  const creds = getIyzicoCredentials()
  if (!creds) {
    throw new Error('Iyzico SDK not initialized')
  }
  const { apiKey, secretKey, baseUrl } = creds
  const uriPath = '/payment/v2/3dsecure/auth'
  const randomString = iyziUtils.generateRandomString(8)
  const body: Record<string, string> = {
    locale: 'tr',
    paymentId: payload.paymentId,
    conversationId: payload.conversationId,
    paidPrice: payload.paidPrice,
    basketId: payload.basketId,
    currency: 'TRY',
  }
  const authorization = iyziUtils.generateAuthorizationHeaderV2(
    'IYZWSv2',
    apiKey,
    ':',
    secretKey,
    uriPath,
    body,
    randomString
  )
  const url = `${baseUrl.replace(/\/+$/, '')}${uriPath}`
  console.log('📤 3DS v2 complete (auth)', { url, paymentId: payload.paymentId })

  const res = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'x-iyzi-rnd': randomString,
      'x-iyzi-client-version': 'iyzipay-node-2.0.64',
      Authorization: authorization,
    },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(10000),
  })

  const result = await res.json().catch(() => ({}))
  console.log('📥 3DS v2 Complete Response:', {
    status: result?.status,
    errorCode: result?.errorCode,
    errorMessage: result?.errorMessage,
    paymentId: result?.paymentId,
    paymentStatus: result?.paymentStatus,
  })
  return result
}

export type IyzicoPaymentResult = {
  status: string
  paymentStatus?: string
  errorMessage?: string
  paymentId?: string
  basketId?: string
  paidPrice?: string | number
  currency?: string
}

/** Ödeme sonucunu conversationId ile sorgula (callback sayfası için) */
export async function retrievePayment(conversationId: string): Promise<IyzicoPaymentResult> {
  const iyzipay = getIyzicoInstance()
  if (!iyzipay) {
    return { status: 'failure', errorMessage: 'Iyzico SDK not initialized' }
  }
  return new Promise((resolve) => {
    const timeout = setTimeout(() => resolve({ status: 'failure', errorMessage: 'Provider query timed out' }), 10000)
    ;(iyzipay as any).payment.retrieve(
      {
        locale: 'tr',
        conversationId: conversationId,
        paymentConversationId: conversationId,
      },
      (err: any, result: any) => {
        clearTimeout(timeout)
        if (err) {
          console.error('❌ Iyzico retrieve error:', err)
          resolve({ status: 'failure', errorMessage: err?.message || 'Sorgu hatası' })
          return
        }
        resolve({
          status: result?.status === 'success' ? 'success' : 'failure',
          paymentStatus: result?.paymentStatus,
          errorMessage: result?.errorMessage,
          paymentId: result?.paymentId,
          basketId: result?.basketId,
          paidPrice: result?.paidPrice,
          currency: result?.currency,
        })
      }
    )
  })
}

